    UNIQUE (namespace, idempotency_digest),
    CHECK ((lease_owner IS NULL) = (lease_expiry_micros IS NULL)),
    CHECK (state = 'running' OR lease_owner IS NULL),
    CHECK (updated_at_micros >= created_at_micros)
